async function api(path, options = {}) {
  const headers = { ...(options.headers || {}) };
  if (appMode === "staff") headers["x-pos-workspace"] = "1";
  else if (currentUser.managerBranchId) headers["x-branch-id"] = currentUser.managerBranchId;
  if (selectedPosBranchId && (path.startsWith("/api/checkout-bookings") || path.startsWith("/api/pos-customers") || path.startsWith("/api/held-sales") || path === "/api/pos-data" || path === "/api/sales" || path === "/api/stock-movements" || path === "/api/branch-bookings" || path === "/api/daily-closing" || path === "/api/time-clock" || path.startsWith("/api/bookings/") || path.startsWith("/api/sales/") || path.startsWith("/api/daily-closing/"))) {
    headers["x-branch-id"] = selectedPosBranchId;

  }
  if (options.body) headers["content-type"] = "application/json";
  const response = await fetch(path, { ...options, headers });
  const result = await response.json();
  if (response.status === 401) { if(appMode!=="admin") throw new Error("Open the branch with its PIN again."); location.href="/login"; throw new Error("Please sign in again."); }
  if (!response.ok) { const error = new Error(result.error || "Request failed"); error.status = response.status; throw error; }
  return result;
}
async function loadData() {
  try {
    message.textContent = "Loading Kunchas data...";
    state = normalizeState(await api("/api/app-data"));
    renderAll();
    if (appMode === "staff") await loadHeldSales();
    message.textContent = "";
  } catch (error) {
    message.textContent = error.message;
  }
}
async function loadPublicBranches() {
  try {
    const response = await fetch("/api/branches-public");
    const result = await response.json();
    const options = '<option value="">Select branch</option>' + result.branches.map((branch) => '<option value="' + branch.id + '">' + esc(branch.name) + '</option>').join("");
    document.querySelector("#posBranch").innerHTML = options;
    if (window.initialBranchId) document.querySelector("#posBranch").value = window.initialBranchId;
  } catch (error) {
    try {
      const branchId = sessionStorage.getItem(OFFLINE_BRANCH_KEY);
      const cached = branchId && await offlineLoad("snapshot:" + branchId);
      if (cached?.branches?.[0]) document.querySelector("#posBranch").innerHTML = '<option value="' + esc(branchId) + '">' + esc(cached.branches[0].name) + '</option>';
      else message.textContent = "Could not load branches.";
    } catch { message.textContent = "Could not load branches."; }
  }
}
